import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert, Button } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE ===================== */
const themeStyle = `
.chart-scroll { overflow-x: auto; overflow-y: hidden; }
.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
  border-radius: 8px 8px 0 0 !important;
  padding: 20px !important;
}
.history-header .card-title { color: white !important; margin: 0 !important; font-weight: bold; font-size: 1.25rem; }
.form-select { border-radius: 12px !important; padding: 8px 15px !important; border: 1px solid #e9ecef !important; font-size: 14px !important; color: #525f7f !important; }
.form-label { font-weight: 700; color: #5e72e4; text-transform: uppercase; font-size: 0.75rem; margin-bottom: 8px; }
.card { border: none !important; box-shadow: 0 0 2rem 0 rgba(136, 152, 170, 0.15) !important; margin-bottom: 30px !important; border-radius: 0.75rem !important; }
.ct-bar { cursor: pointer; transition: opacity 0.2s; }
.ct-bar:hover { opacity: 0.7; }
`;

const CAMERA_MAP = { CAM01: "วิศวะ", CAM02: "วิทยาศาสตร์", CAM03: "ศิลปศาสตร์", CAM04: "PKY" };

function History() {
  const currentYearBE = new Date().getFullYear() + 543;
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [cameraId, setCameraId] = useState("CAM01");

  const [rawFileData, setRawFileData] = useState([]); // เก็บข้อมูลดิบจาก API ทั้งหมด
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [detailChart, setDetailChart] = useState(null); // เก็บข้อมูลรายนาทีของชั่วโมงที่เลือก
  const [selectedHour, setSelectedHour] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" }, { val: "03", name: "มีนาคม" },
    { val: "04", name: "เมษายน" }, { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" }, { val: "09", name: "กันยายน" },
    { val: "10", name: "ตุลาคม" }, { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" },
  ];

  const handleSearch = async () => {
    setIsLoaded(false);
    setDetailChart(null);
    setSelectedHour(null);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    
    try {
      const res = await fetch(`http://localhost:3001/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=07:00&endTime=22:00`);
      const result = await res.json();

      if (result && result.labels) {
        setRawFileData(result); // เก็บข้อมูลดิบไว้ทำ Drill-down
        
        // ประมวลผลรายชั่วโมง
        const bucket = {};
        result.labels.forEach((label, idx) => {
          const hour = label.split(":")[0].padStart(2, '0') + ":00";
          if (!bucket[hour]) bucket[hour] = { sum: 0, count: 0 };
          bucket[hour].sum += result.series[0][idx];
          bucket[hour].count += 1;
        });

        const labels = [], series = [];
        for (let i = 7; i <= 22; i++) {
          const h = i.toString().padStart(2, '0') + ":00";
          labels.push(h);
          series.push(bucket[h] ? Math.round(bucket[h].sum / bucket[h].count) : 0);
        }
        setChartState({ labels, series: [series] });
      } else {
        setChartState({ labels: [], series: [[]] });
      }
    } catch (err) { console.error(err); }
    setIsLoaded(true);
  };

  useEffect(() => { handleSearch(); }, [selectedDay, selectedMonth, selectedYearBE, cameraId]);

  // ฟังก์ชันสีตามระดับความหนาแน่น
  const getDensityColor = (value) => {
    if (value >= 41) return "#f5365c"; // แดง (หนาแน่นมาก)
    if (value >= 31) return "#fb6340"; // ส้ม (หนาแน่น)
    if (value >= 21) return "#ffd600"; // เหลือง (เริ่มหนาแน่น)
    return "#2dce89"; // เขียว (ปกติ)
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      data.element.attr({ style: `stroke: ${getDensityColor(data.value.y)}; stroke-width: 25px;` });
      data.group.elem("text", { x: data.x2, y: data.y2 - 12, style: "font-size:12px; font-weight:bold; text-anchor:middle; fill:#333;" }).text(data.value.y);
    }
  };

  // ดักจับการคลิกเพื่อดูรายนาที
  const chartEvents = {
    draw: drawBarLabels,
    created: (context) => {
      context.svg.on('click', (e) => {
        const target = e.target;
        if (target.className.baseVal.includes('ct-bar')) {
          const value = target.getAttribute('ct:value');
          const index = target.parentNode.firstChild === target ? 0 : Array.from(target.parentNode.childNodes).indexOf(target);
          const hourLabel = chartState.labels[index];
          
          // กรองข้อมูลเฉพาะนาทีในชั่วโมงนั้น
          const detailLabels = [];
          const detailSeries = [];
          rawFileData.labels.forEach((l, i) => {
            if (l.startsWith(hourLabel.split(":")[0])) {
              detailLabels.push(l);
              detailSeries.push(rawFileData.series[0][i]);
            }
          });

          setSelectedHour(hourLabel);
          setDetailChart({ labels: detailLabels, series: [detailSeries] });
        }
      });
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>
      {/* ส่วนเลือกข้อมูล */}
      <Card><Card.Header className="history-header"><Card.Title as="h4">สถิติความหนาแน่นรายชั่วโมง</Card.Title></Card.Header>
        <Card.Body><Row className="align-items-end"><Col md="4"><Form.Label className="form-label">สถานที่</Form.Label>
          <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
            {Object.entries(CAMERA_MAP).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
          </Form.Select></Col>
          <Col md="8"><Form.Label className="form-label">วันที่</Form.Label><div className="d-flex gap-2">
            <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</Form.Select>
            <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>{monthsThai.map(m=><option key={m.val} value={m.val}>{m.name}</option>)}</Form.Select>
            <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}><option value={currentYearBE}>{currentYearBE}</option><option value={currentYearBE-1}>{currentYearBE-1}</option></Form.Select>
          </div></Col></Row></Card.Body></Card>

      {/* กราฟหลัก */}
      {isLoaded && chartState.labels.length > 0 && (
        <Card><Card.Body>
          <h5 className="mb-4">กราฟรายชั่วโมง: {CAMERA_MAP[cameraId]} <small className="text-muted">(คลิกที่แท่งเพื่อดูรายนาที)</small></h5>
          <div className="chart-scroll"><div style={{ width: "100%", minWidth: "800px", height: "400px" }}>
            <ChartistGraph data={chartState} type="Bar" options={{ low: 0, fullWidth: true, chartPadding: { top: 30 } }} listener={chartEvents} />
          </div></div>
          <div className="d-flex gap-3 justify-content-center mt-3 small">
            <span><i className="fa fa-circle" style={{color:'#2dce89'}}></i> 0-20 (ปกติ)</span>
            <span><i className="fa fa-circle" style={{color:'#ffd600'}}></i> 21-30 (เริ่มหนาแน่น)</span>
            <span><i className="fa fa-circle" style={{color:'#fb6340'}}></i> 31-40 (หนาแน่น)</span>
            <span><i className="fa fa-circle" style={{color:'#f5365c'}}></i> 41+ (หนาแน่นมาก)</span>
          </div>
        </Card.Body></Card>
      )}

      {/* กราฟรายละเอียดรายนาที (Drill-down) */}
      {detailChart && (
        <Card className="border-primary" style={{borderWidth:'2px !important'}}>
          <Card.Header className="bg-transparent d-flex justify-content-between align-items-center">
            <h5 className="mb-0 text-primary font-weight-bold">ข้อมูลรายนาที ช่วงเวลา {selectedHour} น.</h5>
            <Button variant="outline-secondary" size="sm" onClick={() => setDetailChart(null)}>ปิด</Button>
          </Card.Header>
          <Card.Body>
            <div className="chart-scroll"><div style={{ width: "100%", minWidth: "800px", height: "300px" }}>
              <ChartistGraph data={detailChart} type="Line" options={{ low: 0, showArea: true, fullWidth: true }} />
            </div></div>
          </Card.Body>
        </Card>
      )}

      {isLoaded && chartState.labels.length === 0 && <Alert variant="warning" className="text-center py-5"><h3>ไม่พบข้อมูลสถิติในวันที่เลือก</h3></Alert>}
    </Container>
  );
}

export default History;
